-- INSERT 가 실패해도 별도 처리 없음

data.after:
CREATE TABLE users (
  id    INTEGER PRIMARY KEY,
  email TEXT NOT NULL UNIQUE
);
-- 앱 코드: 사전 SELECT 는 조기 응답용으로 유지
-- INSERT 의 유니크 위반 오류를 잡아 409 Conflict 로 응답

