-- 이미 쌓인 중복 이메일
SELECT email, count(*) FROM users GROUP BY email HAVING count(*) > 1;

-- 고아 행: users 에 부모가 없는 orders
SELECT o.id, o.user_id
FROM orders o LEFT JOIN users u ON u.id = o.user_id
WHERE u.id IS NULL;
